CREATE SEQUENCE "ORDERS_SEQ";

CREATE TABLE "ORDERS" (
  "ID" NUMBER(10) NOT NULL,
  "ORDER_NO" VARCHAR2(64 BYTE) NOT NULL,
  "TOTAL" NUMBER(10,2) DEFAULT 0,
  "CREATED" DATE DEFAULT SYSDATE,
  CONSTRAINT "ORDERS_NO_UQ" UNIQUE ("ORDER_NO"),
  CONSTRAINT "ORDERS_PK" PRIMARY KEY ("ID"),
  CONSTRAINT "ORDERS_TOTAL_CK" CHECK (TOTAL >= 0)
);

CREATE INDEX "ORDERS_CREATED_IDX" ON "ORDERS" ("CREATED" ASC);

CREATE VIEW "ORDERS_VIEW" AS SELECT ID, ORDER_NO FROM TEST_1.ORDERS;
